"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["85733"],{33773(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>c,frontMatter:()=>a,contentTitle:()=>i,toc:()=>l,assets:()=>h});var s=JSON.parse('{"id":"2002posts/2002poems3","title":"","description":"I originally had no interest in internet matters. By chance I spotted the great news from the Chinese Recitation Forum and couldn\'t help leaping with joy. Recitation \u2014 it is my foremost passion in life. I had thought this was a private affair, never imagining that today\'s technology has advanced so far as to set up forums for it. My excitement is truly like the surging waters of the Yangtze, unstoppable. I humbly hope that fellow recitation brothers, sisters, madams, misses, ducks, and birds will embrace and accommodate me, granting me this chicken-opportunity to contribute a portion of essence and heat toward creating a new era for the Chinese Recitation Forum.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/2002posts/2002poems3.md","sourceDirName":"2002posts","slug":"/2002posts/2002poems3","permalink":"/en/2002posts/2002poems3","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"2002poems3","title":"","hide_table_of_contents":true,"sidebar_label":"Great news from China\'s lewd forums"},"sidebar":"y2002postsSidebar","previous":{"title":"Collection of Xiaoren1\'s works from one month online (excluding content too inappropriate for children)","permalink":"/en/2002posts/2002poems2"},"next":{"title":"Come when fate arrives, leave when fate ends, settling matters on one\'s own \u2014 also a farewell to Xutang","permalink":"/en/2002posts/2002poems4"}}'),r=t(74848),o=t(28453);let a={id:"2002poems3",title:"",hide_table_of_contents:!0,sidebar_label:"Great news from China's lewd forums"},i="Great News from the Chinese Recitation Forum",h={},l=[];function d(e){let n={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"great-news-from-the-chinese-recitation-forum",children:"Great News from the Chinese Recitation Forum"})}),"\n",(0,r.jsxs)(n.p,{children:["I originally had no interest in internet matters. By chance I spotted the great news from the Chinese Recitation Forum and couldn't help leaping with joy. Recitation \u2014 it is my foremost passion in life. I had thought this was a private affair, never imagining that today's technology has advanced so far as to set up forums for it. My excitement is truly like the surging waters of the Yangtze, unstoppable. I humbly hope that fellow recitation brothers, sisters, madams, misses, ducks, and birds will embrace and accommodate me, granting me this chicken-opportunity to contribute a portion of essence and heat toward creating a new era for the Chinese Recitation Forum.",(0,r.jsx)("br",{}),"\nXiaoren bows in reverence"]}),"\n",(0,r.jsxs)(n.p,{children:["Each generation produces its heroes",(0,r.jsx)("br",{}),"\nEach misleading the masses for decades",(0,r.jsx)("br",{}),"\nToday, just look at the internet guests",(0,r.jsx)("br",{}),"\nIn the lewd forum, the wavy society, stirring sour drool"]}),"\n",(0,r.jsxs)(n.p,{children:["A thousand and some hands, twenty yuan apiece",(0,r.jsx)("br",{}),"\nRegular clients and new flames always biased",(0,r.jsx)("br",{}),"\nIf you're flush enough for five mouths",(0,r.jsx)("br",{}),"\nSend you off with 20% off \u2014 sealing our dusty fate"]}),"\n",(0,r.jsxs)(n.p,{children:["Clouds confuse and mist obscures the old pavilion pool",(0,r.jsx)("br",{}),"\nHer longing and his love remain unresolved",(0,r.jsx)("br",{}),"\nWhat day will the spring night see your rising again?",(0,r.jsx)("br",{}),"\nAcross the river, wind and rain are all lustful verse"]}),"\n",(0,r.jsxs)(n.p,{children:["Love rises at the moon by heaven's edge",(0,r.jsx)("br",{}),"\nEssence is born from phlegm at the bottom of the heart",(0,r.jsx)("br",{}),"\nThe red dust has many amusing things",(0,r.jsx)("br",{}),"\nIn the Eastern Land, there is a Recitation Forum",(0,r.jsx)("br",{}),"\nGrand indeed, the Viagra Tower",(0,r.jsx)("br",{}),"\nFirm indeed, the Holy Maiden's Nunnery",(0,r.jsx)("br",{}),"\nSpirit-wandering adds vigor",(0,r.jsx)("br",{}),"\nDay and night, pounding the Dragon Pool"]}),"\n",(0,r.jsxs)(n.p,{children:["Doggerel doesn't matter",(0,r.jsx)("br",{}),"\nAs long as the quality is there",(0,r.jsx)("br",{}),"\nRub a few times now and then",(0,r.jsx)("br",{}),"\nRevolution is always victorious"]}),"\n",(0,r.jsxs)(n.p,{children:["The Great River flows east, occasionally I look back",(0,r.jsx)("br",{}),"\nReining the horse, leveling the spear, competing to go upstream",(0,r.jsx)("br",{}),"\nThe homeland's divine oil protects the body",(0,r.jsx)("br",{}),"\nRomantic figures become even more romantic"]}),"\n",(0,r.jsxs)(n.p,{children:["Roaming heaven and earth, trapped by heaven and earth",(0,r.jsx)("br",{}),"\nA heart that won't fall still yearns for the bird-wind",(0,r.jsx)("br",{}),"\nThe bear does tricks, the dog barks",(0,r.jsx)("br",{}),"\nThe hero and the bear are all the same bear"]}),"\n",(0,r.jsxs)(n.p,{children:["If below won't cut below",(0,r.jsx)("br",{}),"\nThen there's really a problem",(0,r.jsx)("br",{}),"\nComing and going, all becomes earth",(0,r.jsx)("br",{}),"\nWhy insist on uniformity?"]}),"\n",(0,r.jsxs)(n.p,{children:["Spring comes but flowers won't bloom",(0,r.jsx)("br",{}),"\nRain scatters but birds still cry",(0,r.jsx)("br",{}),"\nThe moon surges through the waters of a thousand rivers",(0,r.jsx)("br",{}),"\nWho can say what is high and what is low?"]}),"\n",(0,r.jsxs)(n.p,{children:["Old Owl erupts in sour speech",(0,r.jsx)("br",{}),"\nOld Madam erupts in angry speech",(0,r.jsx)("br",{}),"\nDay doesn't understand the darkness of night",(0,r.jsx)("br",{}),"\nWooden bird, dumb bird, in labor again"]}),"\n",(0,r.jsxs)(n.p,{children:["Sex is the primary productive force",(0,r.jsx)("br",{}),"\nTechnology can't compare with visiting a courtesan",(0,r.jsx)("br",{}),"\nWhen eating eggs, eat atomic eggs",(0,r.jsx)("br",{}),"\nStriding boldly into the new century"]}),"\n",(0,r.jsxs)(n.p,{children:["In the old days when the family had little rice",(0,r.jsx)("br",{}),"\nOn the Eastern Sea I was a salt smuggler",(0,r.jsx)("br",{}),"\nThe gun is a bird flushed from the woods",(0,r.jsx)("br",{}),"\nThe heart is like a cat mourning the mouse",(0,r.jsx)("br",{}),"\nPainted on the two breasts in cinnabar",(0,r.jsx)("br",{}),"\nBlack and white described in one breath",(0,r.jsx)("br",{}),"\nWho speaks of the valor of yesteryear?",(0,r.jsx)("br",{}),"\nToday's sirens work the platform"]}),"\n",(0,r.jsxs)(n.p,{children:["Who is not born of nature?",(0,r.jsx)("br",{}),"\nWho does not arise from nature?",(0,r.jsx)("br",{}),"\nWhite night and black day",(0,r.jsx)("br",{}),"\nAnother century done"]}),"\n",(0,r.jsxs)(n.p,{children:["In the human world, life's grievances are empty,",(0,r.jsx)("br",{}),"\nWine, lust, wealth, fame \u2014 desires all differ.",(0,r.jsx)("br",{}),"\nWhy does Eden have its forbidden fruit?",(0,r.jsx)("br",{}),"\nWho seeks sin, dreaming in heaven?"]}),"\n",(0,r.jsxs)(n.p,{children:["When nature is frequent, thought grows frequent too",(0,r.jsx)("br",{}),"\nWhen thought is frequent, the tongue grows poor",(0,r.jsx)("br",{}),"\nHeaven and earth are but a single sheet of paper",(0,r.jsx)("br",{}),"\nEach character, a star"]}),"\n",(0,r.jsxs)(n.p,{children:["Appendix: Great News from the Chinese Recitation Forum",(0,r.jsx)("br",{}),"\nOriginal pure vitality, the voice of blood and tears of the common people",(0,r.jsx)("br",{}),'\n------Liao Guohua\'s poetry collection "Chants from the Studio of No Delusion" is published',(0,r.jsx)("br",{}),"\nWith a preface by Old Owl and title calligraphy by the renowned Taiwanese painter and calligrapher Kong Yiping, Liao Guohua's poetry collection has been ceremoniously published, containing over 1,000 works. Each copy is priced at 20 yuan with free shipping. Those who identify as friends of Old Owl, internet friends, or order 5 or more copies receive a 20% discount.",(0,r.jsx)("br",{}),"\nAddress: Liao Guohua, Jisheng Village, Mishi Town, Jingzhou City, Hubei Province",(0,r.jsx)("br",{}),"\nPostal code: 434144",(0,r.jsx)("br",{}),"\nHome phone: 0716---8817427"]})]})}function c(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>a,x:()=>i});var s=t(96540);let r={},o=s.createContext(r);function a(e){let n=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),s.createElement(o.Provider,{value:n},e.children)}}}]);